const body = $input.item.json.body ?? $input.item.json;
return [{
  json: {
    alertId: body.alertId ?? body.alert_id,
    organizationId: body.organizationId ?? body.organization_id,
    customerId: body.customerId ?? body.customer_id,
    transactionId: body.transactionId ?? body.transaction_id ?? null,
    alertType: body.alertType ?? body.alert_type,
    severity: body.severity,
    triggeredRules: body.triggeredRules ?? body.triggered_rules ?? [],
    riskScore: body.riskScore ?? body.risk_score ?? null,
    mlScore: body.mlScore ?? body.ml_score ?? null,
    source: body.source ?? 'EXTERNAL_SYSTEM',
    occurredAt: body.occurredAt ?? body.occurred_at ?? new Date().toISOString()
  }
}];

const crypto = require('crypto');
const payload = $input.item.json;
const body = JSON.stringify(payload);
const secret = $env.AML_WEBHOOK_SECRET;
const signature = 'sha256=' + crypto.createHmac('sha256', secret).update(body).digest('hex');
return [{ json: { body, signature, payload } }];
